struct RemoveList {
 virtual ~RemoveList(){Clear(true);}
 virtual IndexPair* Allocate(unsigned);
 virtual void Deallocate(IndexPair*);
 virtual IndexPair* Reallocate(IndexPair*,unsigned);
 IndexPair* data;unsigned count,capacity;
 unsigned Size()const{return count;} IndexPair* At(unsigned i){return &data[i];}
 RemoveList(){InitialSetup(0,0);}
 void InitItems(IndexPair* items,unsigned n){if(n==0)return;for(unsigned i=0;i<n;++i)new(&items[i])IndexPair;}
 void InitialSetup(unsigned requested,unsigned saved){data=0;count=0;capacity=0;if(saved>requested)requested=saved;if(requested>0){data=Allocate(requested);capacity=requested;}if(saved>0){InitItems(data,saved);count=saved;}}
 void ReleaseItems(IndexPair* items,unsigned n){for(unsigned i=0;i<n;++i)items[i].~IndexPair();}
 void Clear(bool release){if(data){ReleaseItems(data,count);if(release){Deallocate(data);data=0;capacity=0;}count=0;}}
 __forceinline unsigned find(const IndexPair& v,unsigned start,bool (*eq)(const IndexPair&,const IndexPair&))const {for(unsigned i=start;i<count;++i)if(data&&eq(data[i],v))return i;return -1;}
 bool IsFull()const{return count==capacity;} unsigned GrowSize()const{return capacity>1024?capacity+1024:capacity*2;}
 // reallocation helper shaped like the engine's (new capacity, entries to keep); these element types reallocate in place
 void Realloc(unsigned n,unsigned keep){data=data?Reallocate(data,n):Allocate(n);}
 __forceinline unsigned ReserveIndex(){if(IsFull()){if(capacity==0){unsigned n=4;data=Allocate(n);capacity=n;}else{unsigned n=GrowSize();Realloc(n,count);capacity=n;}}count=count+1;return count-1;}
 __forceinline void add(const IndexPair& v){unsigned k=ReserveIndex();InitItems(data+k,1);data[k]=v;}
};
